using System.Data; using MediDesk.Business.Interfaces; using MediDesk.Common.Contracts.Catalog; using MediDesk.Common.Contracts.Operations; using Microsoft.Data.SqlClient;
namespace MediDesk.Data.Repositories;
public sealed class ReturnRepository(SqlConnectionFactory f):IReturnRepository {
 public async Task<PagedResponse<SaleReturnDto>> GetPageAsync(ReturnQuery q,CancellationToken ct){var sql="SELECT COUNT(1) FROM dbo.SaleReturns WHERE IsDeleted=0 AND (@S IS NULL OR ReturnNumber LIKE @L OR InvoiceNumber LIKE @L OR CustomerName LIKE @L); SELECT Id,ReturnNumber,SaleId,InvoiceNumber,CustomerName,Reason,Amount,Status,CreatedAtUtc FROM dbo.SaleReturns WHERE IsDeleted=0 AND (@S IS NULL OR ReturnNumber LIKE @L OR InvoiceNumber LIKE @L OR CustomerName LIKE @L) ORDER BY CreatedAtUtc DESC OFFSET @O ROWS FETCH NEXT @P ROWS ONLY;";await using var c=f.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand(sql,c);cmd.Parameters.Add("@S",SqlDbType.NVarChar,160).Value=(object?)q.Search??DBNull.Value;cmd.Parameters.Add("@L",SqlDbType.NVarChar,170).Value=q.Search is null?DBNull.Value:$"%{q.Search}%";cmd.Parameters.Add("@O",SqlDbType.Int).Value=(q.Page-1)*q.PageSize;cmd.Parameters.Add("@P",SqlDbType.Int).Value=q.PageSize;await using var rd=await cmd.ExecuteReaderAsync(ct);await rd.ReadAsync(ct);var total=rd.GetInt32(0);await rd.NextResultAsync(ct);var list=new List<SaleReturnDto>();while(await rd.ReadAsync(ct))list.Add(new(rd.GetInt64(0),rd.GetString(1),rd.GetInt64(2),rd.GetString(3),rd.GetString(4),rd.GetString(5),rd.GetDecimal(6),rd.GetString(7),DateTime.SpecifyKind(rd.GetDateTime(8),DateTimeKind.Utc),Array.Empty<SaleReturnLineDto>()));return new(list,q.Page,q.PageSize,total);}
 public async Task<SaleReturnDto> CreateSaleReturnAsync(CreateSaleReturnRequest r,long u,CancellationToken ct){await using var c=f.Create();await c.OpenAsync(ct);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var h="SELECT InvoiceNumber=CONCAT('INV-',YEAR(CreatedAtUtc),'-',RIGHT('000000'+CAST(Id AS VARCHAR(6)),6)),CustomerName FROM dbo.Sales WITH(UPDLOCK) WHERE Id=@Id AND IsDeleted=0 AND Status='Completed';";await using var hc=new SqlCommand(h,c,tx);hc.Parameters.Add("@Id",SqlDbType.BigInt).Value=r.SaleId;await using var hr=await hc.ExecuteReaderAsync(ct);if(!await hr.ReadAsync(ct))throw new KeyNotFoundException("Sale invoice not found or already cancelled.");var invoice=hr.GetString(0);var customer=hr.IsDBNull(1)?"Walk-in":hr.GetString(1);await hr.DisposeAsync();decimal amount=0;var lines=new List<SaleReturnLineDto>();foreach(var item in r.Items){await using var ic=new SqlCommand("SELECT si.MedicineId,si.MedicineName,si.Quantity,si.LineTotal,COALESCE((SELECT SUM(Quantity) FROM dbo.SaleReturnItems sri JOIN dbo.SaleReturns sr ON sr.Id=sri.ReturnId WHERE sri.SaleItemId=si.Id AND sr.IsDeleted=0),0) FROM dbo.SaleItems si WHERE si.Id=@Id AND si.SaleId=@Sale AND si.IsDeleted=0",c,tx);ic.Parameters.Add("@Id",SqlDbType.BigInt).Value=item.SaleItemId;ic.Parameters.Add("@Sale",SqlDbType.BigInt).Value=r.SaleId;await using var ir=await ic.ExecuteReaderAsync(ct);if(!await ir.ReadAsync(ct))throw new KeyNotFoundException("Sale item not found.");var med=ir.GetInt64(0);var name=ir.GetString(1);var sold=ir.GetInt32(2);var lineTotal=ir.GetDecimal(3);var already=ir.GetInt32(4);await ir.DisposeAsync();if(item.Quantity>sold-already)throw new InvalidOperationException($"Return quantity for {name} exceeds sold quantity.");var lineAmount=Math.Round(lineTotal*item.Quantity/sold,2);amount+=lineAmount;lines.Add(new(item.SaleItemId,med,name,item.Quantity,lineAmount));await using var stock=new SqlCommand("UPDATE dbo.Medicines SET Stock=Stock+@Q,UpdatedByUserId=@U,UpdatedAtUtc=SYSUTCDATETIME() WHERE Id=@M AND IsDeleted=0; INSERT dbo.InventoryMovements(MedicineId,MovementType,QuantityChange,PreviousStock,NewStock,Reason,ReferenceNumber,CreatedByUserId) SELECT @M,'SaleReturn',@Q,Stock-@Q,Stock,'Sale return',@Ref,@U FROM dbo.Medicines WHERE Id=@M;",c,tx);stock.Parameters.Add("@Q",SqlDbType.Int).Value=item.Quantity;stock.Parameters.Add("@M",SqlDbType.BigInt).Value=med;stock.Parameters.Add("@U",SqlDbType.BigInt).Value=u;stock.Parameters.Add("@Ref",SqlDbType.NVarChar,80).Value=$"RET-{r.SaleId}";await stock.ExecuteNonQueryAsync(ct);}
var insert="INSERT dbo.SaleReturns(SaleId,InvoiceNumber,CustomerName,Reason,Amount,Status,CreatedByUserId) OUTPUT INSERTED.Id,INSERTED.CreatedAtUtc VALUES(@Sale,@Inv,@Customer,@Reason,@Amount,'Completed',@U);";await using var cmd=new SqlCommand(insert,c,tx);cmd.Parameters.Add("@Sale",SqlDbType.BigInt).Value=r.SaleId;cmd.Parameters.Add("@Inv",SqlDbType.NVarChar,40).Value=invoice;cmd.Parameters.Add("@Customer",SqlDbType.NVarChar,160).Value=customer;cmd.Parameters.Add("@Reason",SqlDbType.NVarChar,300).Value=r.Reason;cmd.Parameters.Add("@Amount",SqlDbType.Decimal).Value=amount;cmd.Parameters.Add("@U",SqlDbType.BigInt).Value=u;await using var x=await cmd.ExecuteReaderAsync(ct);await x.ReadAsync(ct);var id=x.GetInt64(0);var at=DateTime.SpecifyKind(x.GetDateTime(1),DateTimeKind.Utc);await x.DisposeAsync();foreach(var line in lines){await using var li=new SqlCommand("INSERT dbo.SaleReturnItems(ReturnId,SaleItemId,MedicineId,MedicineName,Quantity,LineTotal) VALUES(@R,@S,@M,@N,@Q,@T)",c,tx);li.Parameters.Add("@R",SqlDbType.BigInt).Value=id;li.Parameters.Add("@S",SqlDbType.BigInt).Value=line.SaleItemId;li.Parameters.Add("@M",SqlDbType.BigInt).Value=line.MedicineId;li.Parameters.Add("@N",SqlDbType.NVarChar,160).Value=line.MedicineName;li.Parameters.Add("@Q",SqlDbType.Int).Value=line.Quantity;li.Parameters.Add("@T",SqlDbType.Decimal).Value=line.LineTotal;await li.ExecuteNonQueryAsync(ct);}await tx.CommitAsync(ct);return new(id,$"RET-{id:000000}",r.SaleId,invoice,customer,r.Reason,amount,"Completed",at,lines);}catch{if(tx.Connection is not null)await tx.RollbackAsync(ct);throw;}}
}

